53	            return LinkClick::runForBlockForeignKey(
54	                function (string $blockColumn) use ($professionalId, $startDate, $endDate) {
55	                    return LinkClick::where('professional_id', $professionalId)
56	                        ->whereBetween('occurred_at', [$startDate, $endDate])
57	                        ->selectRaw("
