108	            $keys[] = CacheKeyGenerator::analyticsVisits($professionalId, $start, $endStr);
109	            $keys[] = CacheKeyGenerator::analyticsClicks($professionalId, $start, $endStr);
110	        }
111	
112	        Cache::deleteMultiple(array_values(array_unique($keys)));
113	    }
