33	    public function pageview(PageviewRequest $request): JsonResponse
34	    {
35	        $data = $request->validated();
36	
37	        // Resolve site by ID or subdomain
38	        $site = $this->resolveSiteFromData($data);
39	
40	        if (! $site) {
41	            // 422 when site_id was given but failed the subdomain cross-check (IDOR attempt).
42	            // 404 when only a subdomain was given and simply wasn't found.
43	            $statusCode = ! empty($data['site_id']) ? 422 : 404;
44	
45	            return $this->error('Site not found', $statusCode);
46	        }
47	
48	        // 404 not 403: public endpoint — returning 403 would reveal the site exists but is unpublished
49	        if (! $site->is_published) {
50	            return $this->error('Site not found', 404);
51	        }
52	
53	        // Create pageview record
54	        $visit = new SiteVisit([
55	            'occurred_at' => now(),
56	            'session_id' => $data['session_id'] ?? null,
57	            'visitor_id' => $data['visitor_id'] ?? null,
58	            'ip_hash' => $this->hashIp($request->ip()),
59	            'user_agent' => $request->userAgent(),
60	            'referrer' => $data['referrer'] ?? $request->headers->get('referer'),
61	            'utm_source' => $data['utm_source'] ?? null,
62	            'utm_medium' => $data['utm_medium'] ?? null,
63	            'utm_campaign' => $data['utm_campaign'] ?? null,
64	            'country_code' => $this->detectCountryCode($request),
65	            'device_type' => $this->detectDeviceType($request->userAgent()),
66	        ]);
67	        $visit->professional_id = $site->professional_id;
68	        $visit->site_id = $site->id;
69	        $visit->save();
70	
71	        try {
72	            $this->analyticsCache->invalidateAnalytics($site->professional_id);
73	        } catch (Throwable) {
74	        }
75	
76	        return $this->success([
77	            'message' => 'Pageview recorded',
78	            'visit_id' => $visit->id,
79	        ], 201);
80	    }
