82	    public function click(ClickRequest $request): JsonResponse
83	    {
84	        $data = $request->validated();
85	
86	        // Resolve site by ID or subdomain
87	        $site = $this->resolveSiteFromData($data);
88	
89	        if (! $site) {
90	            // 422 when site_id was given but failed the subdomain cross-check (IDOR attempt).
91	            // 404 when only a subdomain was given and simply wasn't found.
92	            $statusCode = ! empty($data['site_id']) ? 422 : 404;
93	
94	            return $this->error('Site not found', $statusCode);
95	        }
96	
97	        // 404 not 403: public endpoint — returning 403 would reveal the site exists but is unpublished
98	        if (! $site->is_published) {
99	            return $this->error('Site not found', 404);
100	        }
101	
102	        // Discard bot traffic silently — fake 200 avoids fingerprinting the filter
103	        if ($this->isBotUserAgent($request->userAgent())) {
104	            return $this->success(['message' => 'Click recorded'], 200);
105	        }
106	
107	        // Verify block exists and belongs to this site
108	        $block = Block::where('id', $data['block_id'])
109	            ->where('site_id', $site->id)
110	            ->first();
111	
112	        if (! $block) {
113	            return $this->error('Block not found or does not belong to this site', 404);
114	        }
115	
116	        $blockGroup = strtolower((string) $block->block_group);
117	        $blockType = strtolower((string) $block->block_type);
118	        $trackableSectionTypes = collect(config('partna.section_block_types', [
119	            'gallery',
120	            'services',
121	            'shop',
122	            'booking',
123	        ]))
124	            ->filter(fn ($type) => is_string($type) && trim($type) !== '')
125	            ->map(fn (string $type) => strtolower(trim($type)))
126	            ->values()
127	            ->all();
128	        $isTrackableLink = $blockGroup === 'links' && $blockType === 'link';
129	        $isTrackableSection =
130	            $blockGroup === 'sections'
131	            && in_array($blockType, $trackableSectionTypes, true);
132	
133	        if (! $isTrackableLink && ! $isTrackableSection) {
134	            return $this->error('Block is not trackable for analytics', 422);
135	        }
136	
137	        // 404 not 403: state check on a public endpoint — 403 reveals the block exists but is disabled
138	        if (! $block->is_active) {
139	            return $this->error('Block not found', 404);
140	        }
141	
142	        // Sanitize referrer: discard values that are not valid URLs (e.g., injected strings)
143	        $rawReferrer = $data['referrer'] ?? $request->headers->get('referer');
144	        $referrer = ($rawReferrer !== null && filter_var($rawReferrer, FILTER_VALIDATE_URL)) ? $rawReferrer : null;
