146	        $click = LinkClick::runForBlockForeignKey(
147	            function (string $blockColumn) use ($request, $data, $site, $block, $referrer) {
148	                // Dedup: return existing click if same visitor/session hit this block within 3 seconds.
149	                $hasIdentifier = ! empty($data['visitor_id']) || ! empty($data['session_id']);
150	                if ($hasIdentifier) {
151	                    $duplicate = LinkClick::where($blockColumn, $block->id)
152	                        ->where(function ($q) use ($data) {
153	                            if (! empty($data['visitor_id'])) {
154	                                $q->orWhere('visitor_id', $data['visitor_id']);
155	                            }
156	                            if (! empty($data['session_id'])) {
157	                                $q->orWhere('session_id', $data['session_id']);
158	                            }
159	                        })
160	                        ->where('occurred_at', '>=', now()->subSeconds(3))
161	                        ->first();
162	
163	                    if ($duplicate) {
164	                        return $duplicate;
165	                    }
166	                }
167	
168	                $click = new LinkClick([
169	                    'occurred_at' => now(),
170	                    'session_id' => $data['session_id'] ?? null,
171	                    'visitor_id' => $data['visitor_id'] ?? null,
172	                    'ip_hash' => $this->hashIp($request->ip()),
173	                    'user_agent' => $request->userAgent(),
174	                    'referrer' => $referrer,
175	                    'utm_source' => $data['utm_source'] ?? null,
176	                    'utm_medium' => $data['utm_medium'] ?? null,
177	                    'utm_campaign' => $data['utm_campaign'] ?? null,
178	                ]);
179	                $click->professional_id = $site->professional_id;
180	                $click->site_id = $site->id;
181	                $click->setAttribute($blockColumn, $block->id);
